772 void llvm::computeKnownBitsFromContext(const Value *V, KnownBits &Known,
773                                        unsigned Depth, const SimplifyQuery &Q) {
774   // Handle injected condition.
775   if (Q.CC && Q.CC->AffectedValues.contains(V))
776     computeKnownBitsFromCond(V, Q.CC->Cond, Known, Depth, Q, Q.CC->Invert);
777 
778   if (!Q.CxtI)
779     return;
780 
781   if (Q.DC && Q.DT) {
782     // Handle dominating conditions.
783     for (BranchInst *BI : Q.DC->conditionsFor(V)) {
784       BasicBlockEdge Edge0(BI->getParent(), BI->getSuccessor(0));
785       if (Q.DT->dominates(Edge0, Q.CxtI->getParent()))
786         computeKnownBitsFromCond(V, BI->getCondition(), Known, Depth, Q,
787                                  /*Invert*/ false);
788 
789       BasicBlockEdge Edge1(BI->getParent(), BI->getSuccessor(1));
790       if (Q.DT->dominates(Edge1, Q.CxtI->getParent()))
791         computeKnownBitsFromCond(V, BI->getCondition(), Known, Depth, Q,
792                                  /*Invert*/ true);
793     }
794 
795     if (Known.hasConflict())
796       Known.resetAll();
797   }
798 
799   if (!Q.AC)
800     return;
801 
802   unsigned BitWidth = Known.getBitWidth();
803 
804   // Note that the patterns below need to be kept in sync with the code
805   // in AssumptionCache::updateAffectedValues.
806 
807   for (AssumptionCache::ResultElem &Elem : Q.AC->assumptionsFor(V)) {
808     if (!Elem.Assume)
809       continue;
810 
811     AssumeInst *I = cast<AssumeInst>(Elem.Assume);
812     assert(I->getParent()->getParent() == Q.CxtI->getParent()->getParent() &&
813            "Got assumption for the wrong function!");
814 
815     if (Elem.Index != AssumptionCache::ExprResultIdx) {
816       if (!V->getType()->isPointerTy())
817         continue;
818       if (RetainedKnowledge RK = getKnowledgeFromBundle(
819               *I, I->bundle_op_info_begin()[Elem.Index])) {
820         if (RK.WasOn == V && RK.AttrKind == Attribute::Alignment &&
821             isPowerOf2_64(RK.ArgValue) &&
822             isValidAssumeForContext(I, Q.CxtI, Q.DT))
823           Known.Zero.setLowBits(Log2_64(RK.ArgValue));
824       }
825       continue;
826     }
827 
828     // Warning: This loop can end up being somewhat performance sensitive.
829     // We're running this loop for once for each value queried resulting in a
830     // runtime of ~O(#assumes * #values).
831 
832     Value *Arg = I->getArgOperand(0);
833 
834     if (Arg == V && isValidAssumeForContext(I, Q.CxtI, Q.DT)) {
835       assert(BitWidth == 1 && "assume operand is not i1?");
836       (void)BitWidth;
837       Known.setAllOnes();
838       return;
839     }
840     if (match(Arg, m_Not(m_Specific(V))) &&
841         isValidAssumeForContext(I, Q.CxtI, Q.DT)) {
842       assert(BitWidth == 1 && "assume operand is not i1?");
843       (void)BitWidth;
844       Known.setAllZero();
845       return;
846     }
847 
848     // The remaining tests are all recursive, so bail out if we hit the limit.
849     if (Depth == MaxAnalysisRecursionDepth)
850       continue;
851 
852     ICmpInst *Cmp = dyn_cast<ICmpInst>(Arg);
853     if (!Cmp)
854       continue;
855 
856     if (!isValidAssumeForContext(I, Q.CxtI, Q.DT))
857       continue;
858 
859     computeKnownBitsFromICmpCond(V, Cmp, Known, Q, /*Invert=*/false);
860   }
861 
862   // Conflicting assumption: Undefined behavior will occur on this execution
863   // path.
864   if (Known.hasConflict())
865     Known.resetAll();
866 }
867 
868 /// Compute known bits from a shift operator, including those with a
869 /// non-constant shift amount. Known is the output of this function. Known2 is a
870 /// pre-allocated temporary with the same bit width as Known and on return
871 /// contains the known bit of the shift value source. KF is an
872 /// operator-specific function that, given the known-bits and a shift amount,
873 /// compute the implied known-bits of the shift operator's result respectively
874 /// for that shift amount. The results from calling KF are conservatively
875 /// combined for all permitted shift amounts.
876 static void computeKnownBitsFromShiftOperator(
877     const Operator *I, const APInt &DemandedElts, KnownBits &Known,
878     KnownBits &Known2, unsigned Depth, const SimplifyQuery &Q,
879     function_ref<KnownBits(const KnownBits &, const KnownBits &, bool)> KF) {
880   computeKnownBits(I->getOperand(0), DemandedElts, Known2, Depth + 1, Q);
881   computeKnownBits(I->getOperand(1), DemandedElts, Known, Depth + 1, Q);
882   // To limit compile-time impact, only query isKnownNonZero() if we know at
883   // least something about the shift amount.
884   bool ShAmtNonZero =
885       Known.isNonZero() ||
886       (Known.getMaxValue().ult(Known.getBitWidth()) &&
887        isKnownNonZero(I->getOperand(1), DemandedElts, Q, Depth + 1));
888   Known = KF(Known2, Known, ShAmtNonZero);
889 }
890 
891 static KnownBits
892 getKnownBitsFromAndXorOr(const Operator *I, const APInt &DemandedElts,
893                          const KnownBits &KnownLHS, const KnownBits &KnownRHS,
894                          unsigned Depth, const SimplifyQuery &Q) {
895   unsigned BitWidth = KnownLHS.getBitWidth();
896   KnownBits KnownOut(BitWidth);
897   bool IsAnd = false;
898   bool HasKnownOne = !KnownLHS.One.isZero() || !KnownRHS.One.isZero();
899   Value *X = nullptr, *Y = nullptr;
900 
901   switch (I->getOpcode()) {
902   case Instruction::And:
903     KnownOut = KnownLHS & KnownRHS;
904     IsAnd = true;
905     // and(x, -x) is common idioms that will clear all but lowest set
906     // bit. If we have a single known bit in x, we can clear all bits
907     // above it.
908     // TODO: instcombine often reassociates independent `and` which can hide
909     // this pattern. Try to match and(x, and(-x, y)) / and(and(x, y), -x).
910     if (HasKnownOne && match(I, m_c_And(m_Value(X), m_Neg(m_Deferred(X))))) {
911       // -(-x) == x so using whichever (LHS/RHS) gets us a better result.
912       if (KnownLHS.countMaxTrailingZeros() <= KnownRHS.countMaxTrailingZeros())
913         KnownOut = KnownLHS.blsi();
914       else
915         KnownOut = KnownRHS.blsi();
916     }
917     break;
918   case Instruction::Or:
919     KnownOut = KnownLHS | KnownRHS;
920     break;
921   case Instruction::Xor:
922     KnownOut = KnownLHS ^ KnownRHS;
923     // xor(x, x-1) is common idioms that will clear all but lowest set
924     // bit. If we have a single known bit in x, we can clear all bits
925     // above it.
926     // TODO: xor(x, x-1) is often rewritting as xor(x, x-C) where C !=
927     // -1 but for the purpose of demanded bits (xor(x, x-C) &
928     // Demanded) == (xor(x, x-1) & Demanded). Extend the xor pattern
929     // to use arbitrary C if xor(x, x-C) as the same as xor(x, x-1).
930     if (HasKnownOne &&
931         match(I, m_c_Xor(m_Value(X), m_c_Add(m_Deferred(X), m_AllOnes())))) {
932       const KnownBits &XBits = I->getOperand(0) == X ? KnownLHS : KnownRHS;
933       KnownOut = XBits.blsmsk();
934     }
935     break;
936   default:
937     llvm_unreachable("Invalid Op used in 'analyzeKnownBitsFromAndXorOr'");
938   }
939 
940   // and(x, add (x, -1)) is a common idiom that always clears the low bit;
941   // xor/or(x, add (x, -1)) is an idiom that will always set the low bit.
942   // here we handle the more general case of adding any odd number by
943   // matching the form and/xor/or(x, add(x, y)) where y is odd.
944   // TODO: This could be generalized to clearing any bit set in y where the
945   // following bit is known to be unset in y.
946   if (!KnownOut.Zero[0] && !KnownOut.One[0] &&
947       (match(I, m_c_BinOp(m_Value(X), m_c_Add(m_Deferred(X), m_Value(Y)))) ||
948        match(I, m_c_BinOp(m_Value(X), m_Sub(m_Deferred(X), m_Value(Y)))) ||
949        match(I, m_c_BinOp(m_Value(X), m_Sub(m_Value(Y), m_Deferred(X)))))) {
